export const M26_ENGAGEMENT_EXTENSION_REGISTRY=Object.freeze([
  Object.freeze({type:'CHECKIN_REGISTRAR',entityType:'checkin',eventName:'REGISTRAR',allowedRoles:Object.freeze(['admin','coach','cliente']),requiresReason:false,requiresPreview:false,snapshotOnApply:false,conflictSensitive:false,bootstrapAllowed:true,enabled:true}),
  Object.freeze({type:'CHECKIN_ANULAR',entityType:'checkin',eventName:'ANULAR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:true,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:true,enabled:true}),
  Object.freeze({type:'HABITO_DEFINIR',entityType:'habit',eventName:'DEFINIR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:false,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:true,enabled:true}),
  Object.freeze({type:'HABITO_REGISTRAR',entityType:'habit_log',eventName:'REGISTRAR',allowedRoles:Object.freeze(['admin','coach','cliente']),requiresReason:false,requiresPreview:false,snapshotOnApply:false,conflictSensitive:false,bootstrapAllowed:true,enabled:true}),
  Object.freeze({type:'HABITO_ARCHIVAR',entityType:'habit',eventName:'ARCHIVAR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:true,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:true,enabled:true}),
  Object.freeze({type:'NOTA_PRIVADA_CREAR',entityType:'private_note',eventName:'CREAR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:false,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:false,enabled:true}),
  Object.freeze({type:'NOTA_PRIVADA_ACTUALIZAR',entityType:'private_note',eventName:'ACTUALIZAR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:false,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:false,enabled:true}),
  Object.freeze({type:'NOTA_PRIVADA_ARCHIVAR',entityType:'private_note',eventName:'ARCHIVAR',allowedRoles:Object.freeze(['admin','coach']),requiresReason:true,requiresPreview:false,snapshotOnApply:false,conflictSensitive:true,bootstrapAllowed:false,enabled:true}),
]);
const REQUIRED_BY_FEATURE=Object.freeze({checkins:['CHECKIN_REGISTRAR'],habits:['HABITO_DEFINIR','HABITO_REGISTRAR','HABITO_ARCHIVAR'],privateNotes:['NOTA_PRIVADA_CREAR','NOTA_PRIVADA_ACTUALIZAR','NOTA_PRIVADA_ARCHIVAR']});
function installedTypes(installed=[]){return new Set(installed.map((item)=>typeof item==='string'?item:item?.type||item?.command_type).filter(Boolean));}
export function engagementCapabilities(installed=[]){const set=installedTypes(installed);const out={};for(const [feature,types] of Object.entries(REQUIRED_BY_FEATURE)){const missing=types.filter((type)=>!set.has(type));out[feature]=Object.freeze({ready:missing.length===0,required:Object.freeze([...types]),missing:Object.freeze(missing)});}return Object.freeze(out);}
export function engagementExtensionContract(){return M26_ENGAGEMENT_EXTENSION_REGISTRY.map((item)=>({...item,allowedRoles:[...item.allowedRoles]}));}
